package com.ptms.controller; import com.ptms.dto.*; import com.ptms.service.*; import jakarta.validation.Valid; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/issues") public class TicketIssueController{private final TicketIssueService s;public TicketIssueController(TicketIssueService s){this.s=s;}@PostMapping("/preview") public IssuePreviewResponse preview(@Valid @RequestBody IssuePreviewRequest q){return s.preview(q);}@PostMapping public IssueResponse create(@Valid @RequestBody CreateIssueRequest q){return s.create(q);}@PostMapping("/{id}/complete") public IssueResponse complete(@PathVariable Long id){return s.complete(id);}@DeleteMapping("/{id}") public void delete(@PathVariable Long id){s.delete(id);}@GetMapping public List<IssueResponse>all(){return s.all();}}
